-- Seeds the two immutable system SSVC methodologies: SSVCv2 (CERT/CC — Deployer,
-- Supplier, Coordinator Triage, Coordinator Publish) and CISAv1 (CISA's own
-- adaptation). Mechanically generated from the tables already verified this session
-- against the official CERTCC/SSVC CSVs (see ares-ui/src/utils/ssvc.ts history) via
-- a one-off script with a round-trip check (tree flattened back to rows == original
-- rows) before this file was written — not hand-typed.











-- Explicit IDs were used above; bump the sequences so future app-generated rows
-- (e.g. a user creating a custom methodology) don't collide with these.
SELECT setval('ares.ssvc_methodology_id_seq', (SELECT MAX(id) FROM ares.ssvc_methodology));
SELECT setval('ares.ssvc_role_id_seq', (SELECT MAX(id) FROM ares.ssvc_role));
SELECT setval('ares.ssvc_tree_node_id_seq', (SELECT MAX(id) FROM ares.ssvc_tree_node));
SELECT setval('ares.ssvc_tree_node_option_id_seq', (SELECT MAX(id) FROM ares.ssvc_tree_node_option));
